begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=49.26683, parking_lng=-117.66282, parking_name='Roadside parking on Sahlstrom Road near the Open Book Wall trail' where path <@ (select path from public.areas where id='bc_kinnaird_bluffs') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 49.26683) / 2), 2) + cos(radians(49.26683)) * cos(radians(lat)) * power(sin(radians(lng - -117.66282) / 2), 2))) <= 4);
update public.areas set parking_lat=49.27891, parking_lng=-117.66108, parking_name='End of the dirt road past 14th Avenue, about 300 m beyond the paved bend' where path <@ (select path from public.areas where id='bc_waterline') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 49.27891) / 2), 2) + cos(radians(49.27891)) * cos(radians(lat)) * power(sin(radians(lng - -117.66108) / 2), 2))) <= 4);
update public.areas set parking_lat=49.32813, parking_lng=-117.63819, parking_name='Wide shoulder on Terrace Road, about 300 m up from Robson Access Road' where path <@ (select path from public.areas where id='bc_mount_sentinel') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 49.32813) / 2), 2) + cos(radians(49.32813)) * cos(radians(lat)) * power(sin(radians(lng - -117.63819) / 2), 2))) <= 4);
commit;
